#include "gtest/gtest.h"
#include "tests/csc/CSCExternalImage.h"
#include "tests/csc/CSCFunctionalModel.h"
#include <cstdlib>
using namespace csc_descriptor;
TEST(CSCExternalImageCorrectnessTest,UsesExportedFP32Semantics){const char*path=std::getenv("CSC_EXTERNAL_IMAGE");if(!path||!*path)GTEST_SKIP()<<"set CSC_EXTERNAL_IMAGE";auto loaded=loadExternalPhysicalImage(path);auto&layout=loaded.layout;std::vector<float>x(layout.matrix.cols);for(uint32_t i=0;i<x.size();++i)x[i]=float((i%13)+1)/7;auto ref=cpuReference(layout.matrix,x);auto got=executeLockstep(layout,x);float error;uint32_t row;EXPECT_TRUE(compareResults(ref,got.y,&error,&row))<<"max_error="<<error<<" row="<<row;EXPECT_EQ(got.stats.active_lanes,layout.stats.nnz);EXPECT_EQ(got.stats.generated_partial_count,layout.stats.nnz);EXPECT_EQ(got.stats.host_accumulation_count,layout.stats.nnz);EXPECT_EQ(got.stats.invalid_lane_multiplication_count,0);EXPECT_EQ(got.stats.invalid_lane_partial_count,0);EXPECT_EQ(got.stats.invalid_lane_accumulation_count,0);EXPECT_EQ(got.stats.value_burst_read_count,got.stats.total_chunks);EXPECT_EQ(got.stats.row_index_burst_read_count,got.stats.total_chunks);EXPECT_EQ(got.stats.logical_csc_mul_events,got.stats.total_chunks);EXPECT_EQ(got.stats.x_scalar_load_count,layout.stats.descriptor_count);EXPECT_EQ(loaded.metadata.fp32_conversion_count,layout.stats.nnz);EXPECT_EQ(loaded.metadata.nan_count,0);EXPECT_EQ(loaded.metadata.inf_count,0);}
